-- Ultimo correlativo emitido en este mes, por tipo de comprobante.
UPDATE sale_types SET sale_type_correlative = '0000007607' WHERE sale_type_id = 1; -- FAC
UPDATE sale_types SET sale_type_correlative = '0000002798' WHERE sale_type_id = 2; -- BOL
